+                            syncScope);
+    auto sourceLoc = materializeSourceLocation(rewriter, loc);
+    auto eventStateTy = getGSanAtomicEventStateType(rewriter);
+    Value eventState = LLVM::AllocaOp::create(rewriter, loc, ptr_ty(ctx),
+                                              eventStateTy, b.i32_val(1), 0);
